81	// partially validated silence.
82	func decodeSilence(body []byte) (*silence, bool) {
83		var raw rawSilence
84		if !strictDecode(body, &raw) {
85			return nil, false
86		}
87		if raw.RuleIDs == nil || raw.StartsAt == nil || raw.EndsAt == nil || raw.Comment == nil {
88			return nil, false
89		}
90	
91		ruleIDs := *raw.RuleIDs
92		if len(ruleIDs) == 0 {
93			return nil, false
94		}
95		seen := make(map[string]bool, len(ruleIDs))
96		for _, id := range ruleIDs {
97			if !identPattern.MatchString(id) || seen[id] {
98				return nil, false
99			}
100			seen[id] = true
101		}
102	
103		startsAt, err := time.Parse(time.RFC3339, *raw.StartsAt)
104		if err != nil {
105			return nil, false
106		}
107		endsAt, err := time.Parse(time.RFC3339, *raw.EndsAt)
108		if err != nil {
109			return nil, false
110		}
111		if !startsAt.Before(endsAt) {
112			return nil, false
113		}
114	
115		return &silence{
116			ruleIDs:     append([]string(nil), ruleIDs...),
117			startsAt:    startsAt,
118			endsAt:      endsAt,
119			comment:     *raw.Comment,
120			startsAtRaw: *raw.StartsAt,
