153	// immutable, so the pointers stay safe after the lock is released.
154	func (s *metricStore) snapshotSilences() []*silence {
155		s.mu.RLock()
156		defer s.mu.RUnlock()
157		out := make([]*silence, 0, len(s.silences))
158		for _, sil := range s.silences {
159			out = append(out, sil)
160		}
161		sort.Slice(out, func(i, j int) bool { return out[i].id < out[j].id })
162		return out
163	}
