184			id := strings.TrimPrefix(r.URL.Path, silencesPrefix)
185			switch r.Method {
186			case http.MethodGet, http.MethodDelete:
187				// Reads and deletions can only address an existing, syntactically
188				// valid silence id; anything else is simply not found.
189				if id == "" || strings.Contains(id, "/") || !identPattern.MatchString(id) {
190					writeAPIError(w, "silence_not_found", http.StatusNotFound)
191					return
192				}
193				if r.Method == http.MethodGet {
194					handleSilenceGet(w, id, store)
195				} else {
196					handleSilenceDelete(w, id, store)
197				}
198			case http.MethodPut:
199				// A structurally nested path is outside this resource subtree;
200				// an identifier-shaped but invalid id is a bad identifier.
201				if id == "" || strings.Contains(id, "/") {
202					writeAPIError(w, "silence_not_found", http.StatusNotFound)
203					return
204				}
205				if !identPattern.MatchString(id) {
206					writeAPIError(w, "invalid_silence", http.StatusBadRequest)
207					return
208				}
209				handleSilencePut(w, r, id, store)
210			default:
211				w.Header().Set("Allow", "GET, PUT, DELETE")
212				writeAPIError(w, "method_not_allowed", http.StatusMethodNotAllowed)
213			}
214		})
