269				continue
270			}
271			for _, ruleID := range sil.ruleIDs {
272				hits[ruleID] = append(hits[ruleID], sil.id)
273			}
274		}
275		for ruleID := range hits {
276			sort.Strings(hits[ruleID])
277		}
278		return hits
279	}
