20	// ruleSelector selects series by exact metric name and a subset of labels.
21	type ruleSelector struct {
22		metric string
23		labels map[string]string
24	}
25	
26	// alertRule is an immutable rule document. Replacements swap the pointer
27	// atomically, so readers never observe a half-updated rule.
28	type alertRule struct {
29		id        string
30		kind      string // "threshold" | "ratio"
31		operator  string // gt | gte | lt | lte
32		threshold float64
33	
34		// threshold rules use left only; ratio rules use both sides.
35		left  *ruleSelector
36		right *ruleSelector
37	}
38	
39	// ---- JSON wire shapes ------------------------------------------------------
40	
41	type ruleSideJSON struct {
42		Metric string            `json:"metric"`
43		Labels map[string]string `json:"labels"`
44	}
45	
46	type thresholdRuleJSON struct {
47		ID        string            `json:"id"`
48		Kind      string            `json:"kind"`
49		Operator  string            `json:"operator"`
50		Threshold float64           `json:"threshold"`
51		Metric    string            `json:"metric"`
52		Labels    map[string]string `json:"labels"`
53	}
54	
55	type ratioRuleJSON struct {
56		ID          string       `json:"id"`
57		Kind        string       `json:"kind"`
58		Operator    string       `json:"operator"`
59		Threshold   float64      `json:"threshold"`
60		Numerator   ruleSideJSON `json:"numerator"`
61		Denominator ruleSideJSON `json:"denominator"`
62	}
63	
64	func ruleWireJSON(r *alertRule) any {
65		if r.kind == "ratio" {
66			return ratioRuleJSON{
67				ID:          r.id,
68				Kind:        r.kind,
69				Operator:    r.operator,
70				Threshold:   r.threshold,
71				Numerator:   sideWireJSON(r.left),
72				Denominator: sideWireJSON(r.right),
73			}
74		}
75		return thresholdRuleJSON{
76			ID:        r.id,
77			Kind:      r.kind,
78			Operator:  r.operator,
79			Threshold: r.threshold,
80			Metric:    r.left.metric,
81			Labels:    copyLabels(r.left.labels),
82		}
83	}
84	
85	func sideWireJSON(s *ruleSelector) ruleSideJSON {
86		return ruleSideJSON{Metric: s.metric, Labels: copyLabels(s.labels)}
87	}
88	
89	// ---- request decoding ------------------------------------------------------
90	
91	type rawRuleSide struct {
92		Metric *string            `json:"metric"`
93		Labels *map[string]string `json:"labels"`
94	}
95	
96	type rawRule struct {
97		Kind        *string            `json:"kind"`
98		Operator    *string            `json:"operator"`
99		Threshold   *float64           `json:"threshold"`
100		Metric      *string            `json:"metric"`
101		Labels      *map[string]string `json:"labels"`
102		Numerator   *rawRuleSide       `json:"numerator"`
103		Denominator *rawRuleSide       `json:"denominator"`
104	}
105	
106	// decodeRule parses and fully validates a rule body. It never returns a
107	// partially validated rule.
108	func decodeRule(body []byte) (*alertRule, bool) {
109		var raw rawRule
110		if !strictDecode(body, &raw) {
111			return nil, false
112		}
113		if raw.Kind == nil || raw.Operator == nil || raw.Threshold == nil {
114			return nil, false
115		}
116		kind := *raw.Kind
117		if kind != "threshold" && kind != "ratio" {
118			return nil, false
119		}
120		operator := *raw.Operator
121		if !validOperators[operator] {
122			return nil, false
123		}
124		threshold := *raw.Threshold
125		if math.IsNaN(threshold) || math.IsInf(threshold, 0) {
126			return nil, false
127		}
128	
129		build := func() *alertRule {
130			return &alertRule{kind: kind, operator: operator, threshold: threshold}
131		}
132	
133		switch kind {
134		case "threshold":
135			if raw.Metric == nil || raw.Labels == nil || raw.Numerator != nil || raw.Denominator != nil {
136				return nil, false
137			}
138			sel, ok := decodeSelector(*raw.Metric, *raw.Labels)
139			if !ok {
140				return nil, false
141			}
142			r := build()
143			r.left = sel
144			return r, true
145		case "ratio":
146			if raw.Metric != nil || raw.Labels != nil || raw.Numerator == nil || raw.Denominator == nil {
147				return nil, false
148			}
149			num, ok := decodeRawSide(raw.Numerator)
150			if !ok {
151				return nil, false
152			}
153			den, ok := decodeRawSide(raw.Denominator)
154			if !ok {
155				return nil, false
156			}
157			r := build()
158			r.left, r.right = num, den
159			return r, true
160		}
161		return nil, false
162	}
163	
164	func decodeRawSide(raw *rawRuleSide) (*ruleSelector, bool) {
165		if raw.Metric == nil || raw.Labels == nil {
166			return nil, false
167		}
168		return decodeSelector(*raw.Metric, *raw.Labels)
169	}
170	
171	func decodeSelector(metric string, labels map[string]string) (*ruleSelector, bool) {
172		if !identPattern.MatchString(metric) || labels == nil {
173			return nil, false
174		}
175		for k := range labels {
176			if !identPattern.MatchString(k) {
177				return nil, false
178			}
179		}
180		return &ruleSelector{metric: metric, labels: copyLabels(labels)}, true
181	}
182	
183	var validOperators = map[string]bool{
184		"gt":  true,
185		"gte": true,
186		"lt":  true,
187		"lte": true,
188	}
189	
190	// ---- store operations ------------------------------------------------------
191	
192	func (s *metricStore) putRule(r *alertRule) bool {
193		s.mu.Lock()
194		defer s.mu.Unlock()
195		_, existed := s.rules[r.id]
196		s.rules[r.id] = r
197		return !existed
198	}
199	
200	func (s *metricStore) getRule(id string) (*alertRule, bool) {
201		s.mu.RLock()
202		defer s.mu.RUnlock()
203		r, ok := s.rules[id]
204		return r, ok
205	}
206	
207	func (s *metricStore) deleteRule(id string) bool {
208		s.mu.Lock()
209		defer s.mu.Unlock()
210		if _, ok := s.rules[id]; !ok {
211			return false
212		}
213		delete(s.rules, id)
214		return true
215	}
216	
217	// snapshotRules returns all rules sorted by id. Rule objects are immutable,
218	// so the pointers stay safe after the lock is released.
219	func (s *metricStore) snapshotRules() []*alertRule {
220		s.mu.RLock()
221		defer s.mu.RUnlock()
222		out := make([]*alertRule, 0, len(s.rules))
223		for _, r := range s.rules {
224			out = append(out, r)
225		}
226		sort.Slice(out, func(i, j int) bool { return out[i].id < out[j].id })
227		return out
228	}
229	
230	// selectorSum sums current values of all matching counter/gauge series.
231	// ok is false when no counter/gauge series matches; histograms are ignored,
232	// so a selector matching histograms only counts as unavailable.
233	func (s *metricStore) selectorSum(sel *ruleSelector) (sum float64, ok bool) {
234		for _, cur := range s.series {
235			if cur.typ != "counter" && cur.typ != "gauge" {
236				continue
237			}
238			if cur.name != sel.metric {
239				continue
240			}
241			matched := true
242			for k, v := range sel.labels {
243				got, exists := cur.labels[k]
244				if !exists || got != v {
245					matched = false
246					break
247				}
248			}
249			if !matched {
250				continue
251			}
252			sum += cur.value
253			ok = true
254		}
255		return sum, ok
256	}
257	
258	type alertOutput struct {
259		ID            string   `json:"id"`
260		State         string   `json:"state"`
261		Value         *float64 `json:"value"`
262		Silenced      bool     `json:"silenced"`
263		SilenceIDs    []string `json:"silence_ids"`
264		Inhibited     bool     `json:"inhibited"`
265		InhibitionIDs []string `json:"inhibition_ids"`
266	}
267	
268	// evalAlerts computes every rule against a single consistent snapshot of
269	// metrics, rules, silences and inhibit rules; results are sorted by rule id.
270	// Original state, value and silencing are evaluated first; inhibition is then
271	// applied to the original firing states so silenced or inhibited alerts still
272	// act as inhibition sources.
273	func (s *metricStore) evalAlerts() []alertOutput {
274		s.mu.RLock()
275		defer s.mu.RUnlock()
276	
277		rules := make([]*alertRule, 0, len(s.rules))
278		for _, r := range s.rules {
279			rules = append(rules, r)
280		}
281		sort.Slice(rules, func(i, j int) bool { return rules[i].id < rules[j].id })
282	
283		silences := make([]*silence, 0, len(s.silences))
284		for _, sil := range s.silences {
285			silences = append(silences, sil)
286		}
287		inhibitRules := make([]*inhibitRule, 0, len(s.inhibitions))
288		for _, ir := range s.inhibitions {
289			inhibitRules = append(inhibitRules, ir)
290		}
291		// Evaluation instant and silence windowing share the snapshot.
292		now := time.Now()
293		activeByRule := activeSilencesByRule(silences, now)
294	
295		out := make([]alertOutput, 0, len(rules))
296		for _, r := range rules {
297			al := alertOutput{ID: r.id, State: "inactive", SilenceIDs: []string{}, InhibitionIDs: []string{}}
298	
299			var value float64
300			if r.kind == "threshold" {
301				sum, ok := s.selectorSum(r.left)
302				if !ok {
303					al.State = "no_data"
304					out = append(out, al)
305					continue
306				}
307				value = sum
308			} else {
309				num, numOK := s.selectorSum(r.left)
310				den, denOK := s.selectorSum(r.right)
311				if !numOK || !denOK || den == 0 {
312					al.State = "no_data"
313					out = append(out, al)
314					continue
315				}
316				value = num / den
317			}
318	
319			v := value
320			al.Value = &v
321			if compareHolds(r.operator, value, r.threshold) {
322				al.State = "firing"
323				if hits := activeByRule[r.id]; len(hits) > 0 {
324					al.Silenced = true
325					al.SilenceIDs = append([]string(nil), hits...)
326				}
327			}
328			out = append(out, al)
329		}
330	
331		applyInhibitions(out, inhibitRules)
332		return out
333	}
334	
335	// applyInhibitions annotates alerts with the inhibit rules that hit them. A
336	// rule hits an alert when the alert's original state is firing and at least
337	// one existing source alert's original state is firing. Sources fire
338	// regardless of their own silenced/inhibited flags, and the target's state,
339	// value and silencing are left untouched.
340	func applyInhibitions(alerts []alertOutput, inhibitRules []*inhibitRule) {
341		firing := make(map[string]bool, len(alerts))
342		for i := range alerts {
343			if alerts[i].State == "firing" {
344				firing[alerts[i].ID] = true
345			}
346		}
347	
348		for i := range alerts {
349			if alerts[i].State != "firing" {
350				continue
351			}
352			var hits []string
353			for _, ir := range inhibitRules {
354				if !containsString(ir.targetRuleIDs, alerts[i].ID) {
355					continue
356				}
357				for _, sourceID := range ir.sourceRuleIDs {
358					if firing[sourceID] {
359						hits = append(hits, ir.id)
360						break
361					}
362				}
363			}
364			if len(hits) > 0 {
365				sort.Strings(hits)
366				alerts[i].Inhibited = true
367				alerts[i].InhibitionIDs = hits
368			}
369		}
370	}
371	
372	func containsString(list []string, want string) bool {
373		for _, v := range list {
374			if v == want {
375				return true
376			}
377		}
378		return false
379	}
380	
381	func compareHolds(operator string, value, threshold float64) bool {
382		switch operator {
383		case "gt":
384			return value > threshold
385		case "gte":
386			return value >= threshold
387		case "lt":
388			return value < threshold
389		case "lte":
390			return value <= threshold
391		}
392		return false
393	}
394	
395	// ---- HTTP handlers ---------------------------------------------------------
396	
397	func registerAlertHandlers(mux *http.ServeMux, store *metricStore) {
398		mux.HandleFunc(alertRulesPath, func(w http.ResponseWriter, r *http.Request) {
399			if r.Method != http.MethodGet {
400				w.Header().Set("Allow", http.MethodGet)
401				writeAPIError(w, "method_not_allowed", http.StatusMethodNotAllowed)
402				return
403			}
404			rules := store.snapshotRules()
405			body := make([]any, 0, len(rules))
406			for _, rule := range rules {
407				body = append(body, ruleWireJSON(rule))
408			}
409			writeJSON(w, http.StatusOK, map[string]any{"rules": body})
410		})
411	
412		mux.HandleFunc(alertRulesPrefix, func(w http.ResponseWriter, r *http.Request) {
413			id := strings.TrimPrefix(r.URL.Path, alertRulesPrefix)
414			switch r.Method {
415			case http.MethodGet, http.MethodDelete:
416				// Reads and deletions can only address an existing, syntactically
417				// valid rule id; anything else is simply not found.
418				if id == "" || strings.Contains(id, "/") || !identPattern.MatchString(id) {
419					writeAPIError(w, "rule_not_found", http.StatusNotFound)
420					return
421				}
422				if r.Method == http.MethodGet {
423					handleRuleGet(w, id, store)
424				} else {
425					handleRuleDelete(w, id, store)
426				}
427			case http.MethodPut:
428				// A structurally nested path is outside this resource subtree;
429				// an identifier-shaped but invalid id is a bad rule identifier.
430				if id == "" || strings.Contains(id, "/") {
431					writeAPIError(w, "rule_not_found", http.StatusNotFound)
432					return
433				}
434				if !identPattern.MatchString(id) {
435					writeAPIError(w, "invalid_rule", http.StatusBadRequest)
436					return
437				}
438				handleRulePut(w, r, id, store)
439			default:
440				w.Header().Set("Allow", "GET, PUT, DELETE")
441				writeAPIError(w, "method_not_allowed", http.StatusMethodNotAllowed)
442			}
443		})
444	
445		mux.HandleFunc(alertsPath, func(w http.ResponseWriter, r *http.Request) {
446			if r.Method != http.MethodGet {
447				w.Header().Set("Allow", http.MethodGet)
448				writeAPIError(w, "method_not_allowed", http.StatusMethodNotAllowed)
449				return
450			}
451			writeJSON(w, http.StatusOK, map[string]any{"alerts": store.evalAlerts()})
452		})
453	}
454	
455	func handleRuleGet(w http.ResponseWriter, id string, store *metricStore) {
456		rule, ok := store.getRule(id)
457		if !ok {
458			writeAPIError(w, "rule_not_found", http.StatusNotFound)
459			return
460		}
461		writeJSON(w, http.StatusOK, ruleWireJSON(rule))
462	}
463	
464	func handleRulePut(w http.ResponseWriter, r *http.Request, id string, store *metricStore) {
465		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
466		if err != nil || mediaType != "application/json" {
467			writeAPIError(w, "unsupported_media_type", http.StatusUnsupportedMediaType)
468			return
469		}
470	
471		body, err := io.ReadAll(r.Body)
472		if err != nil {
473			writeAPIError(w, "invalid_rule", http.StatusBadRequest)
474			return
475		}
476	
477		rule, ok := decodeRule(body)
478		if !ok {
479			writeAPIError(w, "invalid_rule", http.StatusBadRequest)
480			return
481		}
482		rule.id = id
483	
484		created := store.putRule(rule)
485		status := http.StatusOK
486		if created {
487			status = http.StatusCreated
488		}
489		writeJSON(w, status, ruleWireJSON(rule))
490	}
491	
492	func handleRuleDelete(w http.ResponseWriter, id string, store *metricStore) {
493		if !store.deleteRule(id) {
494			writeAPIError(w, "rule_not_found", http.StatusNotFound)
495			return
496		}
497		w.WriteHeader(http.StatusNoContent)
498	}
499	
500	func writeJSON(w http.ResponseWriter, status int, payload any) {
501		w.Header().Set("Content-Type", "application/json; charset=utf-8")
502		w.WriteHeader(status)
503		_ = json.NewEncoder(w).Encode(payload)
504	}
505

