	if st != 201 { t.Fatalf("rule2: %d", st) }

	// create route
	st, body, _ := req(t, h, "PUT", "/api/v1/notification-routes/rt1", "application/json", `{"rule_ids":["r1","nope"],"receiver":"ops","priority":10,"comment":null}`)
	if st != 201 || body["id"] != "rt1" || body["receiver"] != "ops" || body["priority"] != 10.0 {
		t.Fatalf("create: %d %v", st, body)
	}
	if c, ok := body["comment"]; !ok || c != nil { t.Fatalf("comment: %v %v", body, ok) }

	// replace -> 200
	st, _, _ = req(t, h, "PUT", "/api/v1/notification-routes/rt1", "application/json", `{"rule_ids":["r1"],"receiver":"ops","priority":5,"comment":"x"}`)
	if st != 200 { t.Fatalf("replace: %d", st) }

	// second route, lower priority wins
	req(t, h, "PUT", "/api/v1/notification-routes/rt0", "application/json", `{"rule_ids":["r1"],"receiver":"backup","priority":1,"comment":"y"}`)

	// plan: r1 firing -> rt0; r2 inactive
	st, body, _ = req(t, h, "GET", "/api/v1/notification-plan", "", "")
	if st != 200 { t.Fatalf("plan: %d", st) }
	d := body["deliveries"].([]any)
	if len(d) != 1 { t.Fatalf("deliveries: %v", body) }
	d0 := d[0].(map[string]any)
	if d0["alert_id"] != "r1" || d0["receiver"] != "backup" || d0["route_id"] != "rt0" {
		t.Fatalf("delivery: %v", d0)
	}
	if len(body["unrouted_alert_ids"].([]any)) != 0 { t.Fatalf("unrouted: %v", body) }

	// delete rt0 -> r1 falls back to rt1
	req(t, h, "DELETE", "/api/v1/notification-routes/rt0", "", "")
	st, body, _ = req(t, h, "GET", "/api/v1/notification-plan", "", "")
	d = body["deliveries"].([]any)
	if d[0].(map[string]any)["route_id"] != "rt1" { t.Fatalf("fallback: %v", body) }

	// delete rt1 -> unrouted
	req(t, h, "DELETE", "/api/v1/notification-routes/rt1", "", "")
	st, body, _ = req(t, h, "GET", "/api/v1/notification-plan", "", "")
	if len(body["deliveries"].([]any)) != 0 { t.Fatalf("empty deliveries: %v", body) }
	u := body["unrouted_alert_ids"].([]any)
	if len(u) != 1 || u[0] != "r1" { t.Fatalf("unrouted: %v", body) }

	// validation errors
	cases := []struct{ body string }{
		{`{"rule_ids":[],"receiver":"a","priority":1,"comment":null}`},
		{`{"rule_ids":["r1","r1"],"receiver":"a","priority":1,"comment":null}`},
		{`{"rule_ids":["r1"],"receiver":"a","priority":-1,"comment":null}`},
		{`{"rule_ids":["r1"],"receiver":"a","priority":1001,"comment":null}`},
		{`{"rule_ids":["r1"],"receiver":"a","priority":1.5,"comment":null}`},
		{`{"rule_ids":["r1"],"receiver":"a","priority":"1","comment":null}`},
		{`{"rule_ids":["r1"],"receiver":"a b","priority":1,"comment":null}`},
		{`{"rule_ids":["r1"],"receiver":"a","priority":1,"comment":null,"extra":1}`},
		{`{"rule_ids":["r1"],"receiver":"a","priority":1,"comment":5}`},
		{`{"rule_ids":["r1"],"receiver":"a"}`},
	}
	for i, c := range cases {
		st, body, _ = req(t, h, "PUT", "/api/v1/notification-routes/bad", "application/json", c.body)
		if st != 400 || body["error"].(map[string]any)["code"] != "invalid_notification_route" {
			t.Fatalf("case %d: %d %v", i, st, body)
		}
	}
	// failed validations must not have created the route
	st, body, _ = req(t, h, "GET", "/api/v1/notification-routes/bad", "", "")
	if st != 404 || body["error"].(map[string]any)["code"] != "notification_route_not_found" {
		t.Fatalf("bad route should not exist: %d %v", st, body)
	}

	// media type
	st, body, _ = req(t, h, "PUT", "/api/v1/notification-routes/x", "text/plain", `{}`)
	if st != 415 || body["error"].(map[string]any)["code"] != "unsupported_media_type" {
		t.Fatalf("415: %d %v", st, body)
	}

	// 404s
	st, body, _ = req(t, h, "DELETE", "/api/v1/notification-routes/missing", "", "")
	if st != 404 || body["error"].(map[string]any)["code"] != "notification_route_not_found" {
		t.Fatalf("delete 404: %d %v", st, body)
	}

	// 405s
	st, body, hdr := req(t, h, "POST", "/api/v1/notification-routes", "application/json", `{}`)
	if st != 405 || hdr.Get("Allow") != "GET" || body["error"].(map[string]any)["code"] != "method_not_allowed" {
		t.Fatalf("collection 405: %d %v %v", st, hdr.Get("Allow"), body)
	}
	st, body, hdr = req(t, h, "POST", "/api/v1/notification-routes/x", "application/json", `{}`)
	if st != 405 || hdr.Get("Allow") != "GET, PUT, DELETE" {
		t.Fatalf("item 405: %d %v", st, hdr.Get("Allow"))
	}
	st, body, hdr = req(t, h, "POST", "/api/v1/notification-plan", "application/json", `{}`)
	if st != 405 || hdr.Get("Allow") != "GET" {
		t.Fatalf("plan 405: %d %v", st, hdr.Get("Allow"))
	}

	// collection GET sorted
	req(t, h, "PUT", "/api/v1/notification-routes/zb", "application/json", `{"rule_ids":["r1"],"receiver":"a","priority":0,"comment":null}`)
	req(t, h, "PUT", "/api/v1/notification-routes/za", "application/json", `{"rule_ids":["r1"],"receiver":"a","priority":1000,"comment":null}`)
	st, body, _ = req(t, h, "GET", "/api/v1/notification-routes", "", "")
	routes := body["routes"].([]any)
	if len(routes) != 2 || routes[0].(map[string]any)["id"] != "za" || routes[1].(map[string]any)["id"] != "zb" {
		t.Fatalf("collection: %v", body)
	}

	// silenced alert excluded from plan
	req(t, h, "PUT", "/api/v1/silences/s1", "application/json", `{"rule_ids":["r1"],"starts_at":"2020-01-01T00:00:00Z","ends_at":"2099-01-01T00:00:00Z","comment":""}`)
	st, body, _ = req(t, h, "GET", "/api/v1/notification-plan", "", "")
	if len(body["deliveries"].([]any)) != 0 || len(body["unrouted_alert_ids"].([]any)) != 0 {
		t.Fatalf("silenced plan: %v", body)
	}
	// baseline alerts endpoint still reports silenced
	st, body, _ = req(t, h, "GET", "/api/v1/alerts", "", "")
	a := body["alerts"].([]any)[0].(map[string]any)
	if a["id"] != "r1" || a["silenced"] != true { t.Fatalf("alerts: %v", body) }
}
EOF
cp /tmp/smoke_test.go internal/server/zz_smoke_test.go && go test ./internal/server/ -run TestSmoke -v; rm internal/server/zz_smoke_test.go
